<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { Building2, Plus } from '@lucide/vue';import { api } from '../api';import Modal from '../components/Modal.vue'
const branches=ref<any[]>([]);const members=ref<any[]>([]);const loading=ref(true);const error=ref('');const success=ref('');const showCreate=ref(false);const selected=ref<any>(null);const saving=ref(false);const form=reactive({name:'',code:'',phone:'',address:''});const memberIds=ref<number[]>([])
async function load(){loading.value=true;try{const [b,m]=await Promise.all([api.get('/branches'),api.get('/team/members')]);branches.value=b.data.branches||[];members.value=m.data.members||m.data.data||m.data||[]}catch(e:any){error.value=e.response?.data?.message||'Branches could not be loaded.'}finally{loading.value=false}}
async function create(){saving.value=true;try{await api.post('/branches',form);showCreate.value=false;Object.assign(form,{name:'',code:'',phone:'',address:''});success.value='Branch created.';await load()}catch(e:any){error.value=Object.values(e.response?.data?.errors||{error:[e.response?.data?.message||'Branch could not be created.']}).flat().join(' ')}finally{saving.value=false}}
function manage(branch:any){selected.value=branch;memberIds.value=(branch.memberships||[]).map((item:any)=>item.id)}
async function saveMembers(){saving.value=true;try{await api.put(`/branches/${selected.value.id}/members`,{membership_ids:memberIds.value});selected.value=null;success.value='Branch access updated.';await load()}catch(e:any){error.value=Object.values(e.response?.data?.errors||{error:[e.response?.data?.message||'Access could not be updated.']}).flat().join(' ')}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="branches-page"><header class="page-heading"><div><span class="eyebrow">MULTI-BRANCH CONTROL</span><h1>Branches</h1><p>Separate day-to-day records by office while keeping company ownership and audit history intact.</p></div><button class="button primary" @click="showCreate=true"><Plus/>New branch</button></header><div v-if="error" class="detail-alert">{{error}}<button @click="error=''">Dismiss</button></div><div v-if="success" class="team-success">{{success}}</div><section class="branch-grid"><article v-for="branch in branches" :key="branch.id" class="panel branch-card"><header><span><Building2/></span><div><h2>{{branch.name}}</h2><small>{{branch.code}} · {{branch.is_main?'Main branch':'Branch office'}}</small></div></header><p>{{branch.address||'No address added'}}</p><footer><span>{{branch.memberships_count}} assigned members</span><button class="button secondary" @click="manage(branch)">Manage access</button></footer></article><div v-if="!loading&&!branches.length" class="panel whatsapp-loading">No accessible branches.</div></section><Modal v-if="showCreate" title="Create branch" @close="showCreate=false"><form class="form-grid" @submit.prevent="create"><label>Branch name<input v-model="form.name" required></label><label>Code<input v-model="form.code" required placeholder="CAIRO-EAST"></label><label>Phone<input v-model="form.phone"></label><label>Address<input v-model="form.address"></label><div class="form-actions full"><button type="button" class="button secondary" @click="showCreate=false">Cancel</button><button class="button primary" :disabled="saving">Create branch</button></div></form></Modal><Modal v-if="selected" :title="`Access · ${selected.name}`" description="Owners and admins can reach every branch. Assign other active members here." @close="selected=null"><form class="branch-member-list" @submit.prevent="saveMembers"><label v-for="member in members" :key="member.id"><input v-model="memberIds" type="checkbox" :value="member.id"><span><strong>{{member.user?.name||member.name}}</strong><small>{{member.role}}</small></span></label><div class="form-actions"><button type="button" class="button secondary" @click="selected=null">Cancel</button><button class="button primary" :disabled="saving">Save access</button></div></form></Modal></div></template>
